def run(out):
    out=Path(out);G=Path('outputs')/ROOTS[1];C=Path('outputs')/ROOTS[0];P=Path('outputs')/ROOTS[2];pub=Path('outputs/r47_publication')
    if out.exists():raise ValueError('Fresh public release')
