    phase_public={k:v for k,v in phase.items() if k not in ('phase_pairs','clock_tasks')};choice_counts=dict(collections.Counter(r['method'] or 'REJECT' for r in guard['records']));summary=dict(source_commit=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),baseline=catalog['config']['baseline'],regression=regression,catalog=dict(sources=source_stats,units=len(lengths),duration_quantiles_frames=np.quantile(lengths,[0,.25,.5,.75,1]).tolist(),shorter_than90_frames=int((lengths<90).sum()),longer_than450_frames=int((lengths>450).sum()),legacy_events_preserved=catalog['legacy_events_preserved'],semantic_complete=False),bridge=evaluation['records'],bridge_counts=dict(methods),G3=dict(nodes=len(edges['nodes']),edges=len(edges['edges']),geometric_edges=sum(e['eligible'] for e in edges['edges']),choices=edges['choices'],node_selection=edges['node_selection'],same_task=False,can_route=False),engineering_guard=dict(policy=guard['policy'],records=guard['records'],counts=choice_counts,posthoc=True,can_route=False,physical_qualified=False),phase=phase_public,independent=ind,browser=browser,receipts=receipts,optimizer_steps=0,new_neural_samples=0,whole_song_generations=0,human_reviewed=False,can_route=False,operational_qualified=False);out.mkdir(parents=True);write(out/'summary.json',summary)
    lines=['# R47：来源覆盖、流形桥与音乐阶段可辨识性','','## 交付与实际结论','','先验收完整来源/新旧事件和G1实际轨迹，再执行G2、G3与阶段对照。正式EDGE/Planner/Native、R41/R43权重、原499事件和R46封存保持冻结。研究代码独立在event_coverage_r47、manifold_bridge_r47、music_phase_r47；本轮训练0、新神经采样0、整曲0。','','- `outputs/event_coverage_r47_01/viewer/index.html`：8条完整录制、旧切口与独立139候选，可选择事件原速播放，无音乐配对或新生成。','- `outputs/manifold_bridge_r47_01/videos/index.html`：四条固定身份、真实256帧来源/G0/G1三栏视频。','- `outputs/manifold_bridge_r47_01/viewer/index.html`：22案例主候选、共同音乐时钟、117帧与逐帧、Root-relative/世界视角。','- `outputs/manifold_bridge_r47_01/viewer_controls/index.html`：G0/G1/G2实际数组对照。','- `outputs/manifold_bridge_r47_01/guard/viewer/index.html`：事后工程选择；Selected复用已保存数组，拒绝案例没有采用输出。','','## P0：完整来源与新候选','','复用R41整录制运动学剖面、阶段及DP目标，改为有界搜索以适应长来源；无保护时与原DP回归相同。保留持续保持/转身及关键速度峰±12帧支持，合并切入保护段的边界，不为满足450帧上限重新截断。原质量未知间隙保持硬边界；没有把最高活动256帧直接命名为原语。',f"新候选{len(lengths)}，最短/中位/最长{int(lengths.min())}/{float(np.median(lengths)):.1f}/{int(lengths.max())}帧；短于90帧{int((lengths<90).sum())}个是不能跨越旧支持间隙的短组件，不伪造上下文；长于450帧{int((lengths>450).sum())}个保留受保护阶段。语义完整性仍UNKNOWN，持续时间长不等于文化演法完整。",'','|来源|完整帧|旧接受帧|质量未知帧|新候选|','|---|---:|---:|---:|---:|']
    for r in source_stats:lines.append(f"|{r['source_uid']}|{r['frames']}|{r['accepted_frames']}|{r['unknown_quality_frames']}|{r['candidate_units']}|")
