    for r in evaluation['records']:
        a=r['methods']['G0'];b=r['methods'].get('G1');s=r['screens'].get('G1');g2=r['certificates'].get('G2',{});ratio='N/A' if a['gap_angle_error_rad'] is None else f"{b['gap_angle_error_rad']/max(a['gap_angle_error_rad'],1e-12):.4f}";lines.append(f"|{r['key']}|{r['baseline_local_chart_eligible']}|{s['gap_D3_ratio']:.4f}|{s['boundary_D3_ratio']:.4f}|{ratio}|{g2.get('observed_boundary_jet_residual',float('nan')):.6g}|")
